# check and enable http/2
echo
nginx -T 2>/dev/null | grep -v '^[[:space:]]*#' | grep -qP 'http2\s+on' || { read -p "Enable HTTP/2? [Y/n] " -n 1 -r; [[ ! $REPLY =~ ^([Nn]|$'\xd1\x82'|$'\xd0\xa2')$ ]] && { grep -riIl '^[[:space:]]*#.*http2\s\+on' /etc/nginx/* 2>/dev/null | xargs -r sed -Ei 's/^[[:space:]]*#.*(http2\s+on)/\1/'; sed -i 's/http2\s\+off;/http2 on;/g' /etc/nginx/nginx.conf 2>/dev/null; grep -qP 'http2\s+on' /etc/nginx/nginx.conf 2>/dev/null || sed -i '/^http\s*{/a \    http2 on;' /etc/nginx/nginx.conf 2>/dev/null; if nginx -t 2>&1 | grep -q "emerg"; then echo "http2 on; failed, trying listen ... http2"; sed -i '/^\s*http2\s\+on;/d' /etc/nginx/nginx.conf; grep -riIl 'listen\s\+[^;]*ssl' /etc/nginx/* 2>/dev/null | xargs -r sed -Ei '/http2/! s/(listen\s+[^;]*ssl)(\s*;)/\1 http2\2/'; nginx -t &>/dev/null && systemctl restart nginx >/dev/null && echo "Result: OK (listen ... http2;)"; else systemctl restart nginx >/dev/null && echo "Result: OK (http2 on;)"; fi } }

# check and disable tlsv1.3
echo
nginx -T 2>/dev/null | grep -v '^[[:space:]]*#' | grep -qP 'ssl_protocols.*TLSv1\.3' && { read -p "Disable TLSv1.3? [Y/n] " -n 1 -r; [[ ! $REPLY =~ ^([Nn]|$'\xd1\x82'|$'\xd0\xa2')$ ]] && { nginx -t &>/dev/null && grep -riIl '^[[:space:]]*ssl_protocols.*TLSv1\.3' /etc/nginx/* 2>/dev/null | xargs -r sed -Ei '/^[[:space:]]*#/!{/TLSv1\.3/ {h;s/^/#/;p;g;s/[[:space:]]*TLSv1\.3//g;}}' && nginx -t &>/dev/null && systemctl restart nginx >/dev/null && echo -n "Result: " && { nginx -T 2>/dev/null | grep -v '^[[:space:]]*#' | grep -qP 'ssl_protocols.*TLSv1\.3' && echo "FAIL (TLSv1.3 still enabled)" || echo "OK (TLSv1.3 disabled)"; }; };
